/* MODULE tu06 · Bước 8 Tối ưu · Khi nào dừng một chiến dịch
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tu06', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tu06-01', skill:'measure', read:'7 phút', t:'Đã tiêu 200 triệu, có nên đổ thêm 100 triệu để “gỡ”?',
  situation:'Một chuỗi trà sữa ở Đà Nẵng chạy chiến dịch ra mắt vị mới được 6 tuần, đã chi 200 triệu. Đơn từ chiến dịch đều đặn nhưng mỗi đơn đang lỗ. Trưởng nhóm nói: “Tiêu 200 triệu rồi, dừng bây giờ là mất trắng. Thêm 100 triệu nữa cho đủ độ nhận biết.” Cả phòng im lặng vì không ai muốn là người nói “bỏ”.',
  concept:{ name:'Chi phí chìm (sunk cost)',
    body:'Tiền đã tiêu không lấy lại được, dù bạn dừng hay chạy tiếp. Vì vậy nó <b>không được</b> là lý do cho quyết định tiếp theo. Câu hỏi đúng chỉ có một: đồng tiền <b>kế tiếp</b> mang về bao nhiêu? Tâm lý tiếc làm người ta muốn “gỡ”, giống người đánh bạc cố thêm ván nữa. Cách tách tâm lý ra: tưởng tượng bạn vừa được giao chiến dịch này hôm nay, chưa tiêu đồng nào — với số liệu hiện tại, bạn có duyệt 100 triệu không?' },
  example:'Số liệu 2 tuần gần nhất: mỗi 10 triệu quảng cáo mang về 80 đơn, lãi gộp mỗi đơn 25.000đ → 2 triệu lãi gộp cho 10 triệu tiêu, tức lỗ 8 triệu trên mỗi 10 triệu. Chạy thêm 100 triệu theo đúng nhịp này là lỗ thêm khoảng 80 triệu. 200 triệu cũ không thay đổi phép tính đó dù bạn chọn gì. Nếu không có bằng chứng nhịp sẽ tốt lên (ví dụ tỉ lệ mua lại đang tăng), quyết định đúng là dừng hoặc sửa, không phải “gỡ”.',
  takeaway:'Tiền đã tiêu không quay lại; chỉ hỏi đồng tiền kế tiếp mang về bao nhiêu.',
  apply:'Nghĩ về một việc bạn đang cố tiếp tục “vì đã bỏ công”. Nói trong 60 giây: nếu hôm nay bắt đầu từ số 0, bạn có chọn làm nó không?',
  mistakes:['Đưa số tiền đã chi vào lý do chạy tiếp.','Dùng “chưa đủ độ nhận biết” làm cớ mà không có số liệu nào đang cải thiện.'],
  q:[
  { type:'mcq', stem:'Chiến dịch đã tiêu 200 triệu và đang lỗ trên từng đơn. Theo bạn, 200 triệu đó nên nặng bao nhiêu trong quyết định chạy tiếp?',
    options:[{k:'a',t:'Rất nặng — tiêu nhiều thế thì phải chạy tiếp để thu hồi lại vốn'},{k:'b',t:'Không nên tính — dù dừng hay chạy, số tiền đó đã mất'},
             {k:'c',t:'Nặng vừa phải — chia đôi, chạy thêm một nửa ngân sách định chi'},{k:'d',t:'Chỉ tính nếu sếp đã duyệt ngân sách lớn ngay từ đầu'}],
    answer:'b', why:{a:'Đây chính là bẫy chi phí chìm: chạy tiếp không làm 200 triệu cũ quay lại, chỉ thêm lỗ mới.',
      b:'Đúng. Tiền đã chi không đổi theo quyết định của bạn, nên không có lý do gì để nó quyết định.',
      c:'Chia đôi là thoả hiệp cảm xúc; nếu nhịp đang lỗ, một nửa ngân sách vẫn là lỗ thêm.',
      d:'Việc ai duyệt ngân sách cũ không đổi được hiệu quả của đồng tiền tiếp theo.'} },
  { type:'mcq', stem:'Trưởng nhóm đề nghị thêm 100 triệu “cho đủ độ nhận biết”. Số liệu 2 tuần gần nhất vẫn lỗ đều. Bạn làm gì?',
    options:[{k:'a',t:'Duyệt 100 triệu, vì dừng giữa chừng làm team mất tinh thần'},{k:'b',t:'Duyệt 100 triệu nhưng dồn hết vào một tuần để tạo cú hích mạnh'},
             {k:'c',t:'Hỏi: nếu hôm nay mới bắt đầu, số liệu này có đáng 100 triệu không?'},{k:'d',t:'Dừng ngay và cắt luôn ngân sách quý sau của cả nhóm'}],
    answer:'c', why:{a:'Tinh thần team quan trọng, nhưng tiêu tiền để giữ tinh thần là dùng sai công cụ.',
      b:'Dồn tiền vào ít ngày thường làm chi phí mỗi đơn tăng chứ không giảm.',
      c:'Đúng. Câu hỏi “bắt đầu từ số 0” tách chi phí chìm ra khỏi quyết định và buộc cả nhóm nhìn số liệu hiện tại.',
      d:'Dừng có thể đúng, nhưng phạt ngân sách quý sau là quyết định khác, không có căn cứ từ một chiến dịch.'} },
  { type:'calc', stem:'Mỗi 10 triệu quảng cáo mang về 80 đơn, lãi gộp mỗi đơn 25.000đ. Nếu chạy thêm 100 triệu theo đúng nhịp này, chiến dịch lỗ thêm bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:80, tol:0.5, wrong:[[20,'ROAS_LA_LOI_NHUAN'],[280,'SAI_TINH_TOAN']], errors:['ROAS_LA_LOI_NHUAN','SAI_TINH_TOAN'],
    steps:['100 triệu = 10 lần 10 triệu → 800 đơn.','Lãi gộp: 800 × 25.000đ = 20 triệu.','Lỗ thêm = 100 − 20 = <b>80 triệu</b>.'] },
  { type:'mcq', stem:'Câu nói nào cho thấy người nói đang mắc bẫy chi phí chìm?',
    options:[{k:'a',t:'“Tuần sau mỗi đơn vẫn lỗ thì mình dừng, như đã hẹn”'},{k:'b',t:'“Tỉ lệ mua lại đang tăng, chạy thêm 2 tuần để đo cho rõ”'},
             {k:'c',t:'“Đã quay xong ba video rồi, không chạy thì phí công cả đội”'},{k:'d',t:'“Chi phí mỗi đơn giảm 3 tuần liền, có thể tăng ngân sách nhẹ”'}],
    answer:'c', why:{a:'Đây là cam kết dừng dựa trên số liệu tương lai, không nhìn vào tiền đã tiêu.',
      b:'Lý do chạy tiếp là một chỉ số đang tốt lên — đó là căn cứ nhìn về phía trước.',
      c:'Đúng. Công quay video đã bỏ ra; nó không làm video hiệu quả hơn nếu chạy.',
      d:'Xu hướng chi phí đang cải thiện là lý do chính đáng để tăng dần.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng mỹ phẩm đã đặt cọc 50 triệu thuê booth hội chợ, nhưng hội chợ bị dời vào tuần trùng đợt bận nhất. Đi thì mất thêm 70 triệu chi phí người và hàng, dự kiến bán được lãi gộp 40 triệu. Cách nghĩ nào đúng?',
    options:[{k:'a',t:'Phải đi, không thì mất trắng 50 triệu tiền cọc đã đặt'},{k:'b',t:'Đi, vì tổng lãi gộp 40 triệu gần bằng tiền cọc'},
             {k:'c',t:'Đi cho có mặt, rút nhân sự về sớm sau nửa ngày'},{k:'d',t:'So 70 triệu phải chi thêm với 40 triệu thu về — đi thì lỗ thêm'}],
    answer:'d', why:{a:'Tiền cọc mất dù đi hay không; nó không nên kéo bạn vào một khoản lỗ mới.',
      b:'So 40 triệu với tiền cọc là so với chi phí chìm; cần so với chi phí phải bỏ thêm.',
      c:'Nửa vời vẫn tốn chi phí cố định dựng booth mà doanh số giảm thêm.',
      d:'Đúng. Chỉ phần chi thêm và phần thu thêm là thay đổi theo quyết định: −70 + 40 = lỗ 30 triệu.'} },
  { type:'mcq', stem:'Vì sao “tưởng tượng mình vừa được giao chiến dịch hôm nay” giúp quyết định tốt hơn?',
    options:[{k:'a',t:'Nó xoá cảm giác tiếc số tiền cũ, chỉ còn số liệu hiện tại'},{k:'b',t:'Nó giúp người mới vào có cớ đổ lỗi cho người quản lý cũ'},
             {k:'c',t:'Nó bắt buộc phải làm lại chiến dịch từ đầu với creative hoàn toàn mới'},{k:'d',t:'Nó làm ngân sách được tính lại từ 0 nên sẽ luôn rẻ hơn'}],
    answer:'a', why:{a:'Đúng. Người mới không mang cảm giác “đã bỏ ra”, nên chỉ nhìn đồng tiền kế tiếp.',
      b:'Mục đích là quyết định đúng, không phải tìm người chịu trách nhiệm.',
      c:'Không bắt phải làm lại; nếu số liệu tốt, người mới vẫn chạy tiếp như cũ.',
      d:'Ngân sách không rẻ đi; chỉ cách nhìn thay đổi.'} },
  { type:'mcq', stem:'Khi nào chạy tiếp một chiến dịch đang lỗ là hợp lý?',
    options:[{k:'a',t:'Khi đã chi quá nửa ngân sách của cả kế hoạch năm cho nó'},{k:'b',t:'Khi có chỉ số dẫn trước đang tốt lên, như mua lại tăng dần'},
             {k:'c',t:'Khi đối thủ cũng đang chạy chiến dịch tương tự và đang lỗ'},{k:'d',t:'Khi cả nhóm đã công bố chiến dịch này trong buổi họp toàn công ty'}],
    answer:'b', why:{a:'Đã chi nhiều là chi phí chìm, không phải bằng chứng sẽ lãi.',
      b:'Đúng. Lỗ hôm nay chấp nhận được nếu có dấu hiệu đo được cho thấy lãi về sau.',
      c:'Đối thủ lỗ không làm bạn lãi; có khi họ cũng đang mắc cùng một bẫy.',
      d:'Sợ mất mặt là tâm lý tiếc, không phải căn cứ kinh doanh.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tu06-02', skill:'creative', read:'7 phút', t:'Chi phí mỗi đơn tăng: do quảng cáo mỏi hay thị trường đã đổi?',
  situation:'Một shop giày thể thao online chạy cùng một bộ video suốt 8 tuần. Tuần 1 chi phí mỗi đơn là 60.000đ, tuần 8 lên 95.000đ. Chủ shop muốn tắt hẳn chiến dịch vì “hết ăn rồi”. Nhân viên chạy quảng cáo thì nghĩ chỉ cần thay video mới.',
  concept:{ name:'Creative mỏi và thị trường đổi',
    body:'Hai nguyên nhân cùng làm chi phí tăng nhưng cách xử lý ngược nhau. <b>Creative mỏi</b>: tần suất (số lần một người thấy) tăng cao, tỉ lệ nhấp giảm dần, nhưng người đã nhấp vẫn mua như cũ — lỗi ở mẩu quảng cáo, thay creative là đủ. <b>Thị trường đổi</b>: tỉ lệ nhấp có thể vẫn ổn, nhưng tỉ lệ mua sau khi nhấp giảm, hoặc mọi creative, kể cả mới, đều đắt lên cùng lúc — nhu cầu, mùa vụ hay đối thủ đã thay đổi. Chỉ trường hợp sau mới là lý do để dừng hoặc thiết kế lại chiến dịch.' },
  example:'Shop giày tách số liệu: tần suất tăng từ 1,4 lên 4,2; tỉ lệ nhấp giảm từ 2,0% còn 1,1%; tỉ lệ mua sau nhấp giữ khoảng 3%. Đây là mô hình creative mỏi. Chủ shop thử 2 video mới trong 1 tuần: chi phí mỗi đơn về 65.000đ. Nếu cả video mới cũng đắt như cũ và tỉ lệ mua sau nhấp giảm, lúc đó mới cần nghĩ tới mùa vụ hay đối thủ.',
  takeaway:'Tách tỉ lệ nhấp và tỉ lệ mua trước khi dừng: mỏi thì thay creative, thị trường đổi mới đổi chiến dịch.',
  apply:'Mở một chiến dịch đang chạy lâu. Nói trong 60 giây: tần suất, tỉ lệ nhấp và tỉ lệ mua sau nhấp đang đi theo hướng nào?',
  mistakes:['Tắt cả chiến dịch khi chỉ một bộ creative mỏi.','Thay creative liên tục khi vấn đề nằm ở nhu cầu thị trường.'],
  q:[
  { type:'mcq', stem:'Chi phí mỗi đơn tăng gần 60% sau 8 tuần chạy cùng một bộ video. Bạn nghĩ nguyên nhân dễ gặp nhất là gì?',
    options:[{k:'a',t:'Thị trường giày thể thao đang suy giảm mạnh trên toàn quốc'},{k:'b',t:'Nền tảng quảng cáo cố tình tăng giá với các shop nhỏ'},
             {k:'c',t:'Người xem đã thấy video quá nhiều lần nên ít nhấp hơn'},{k:'d',t:'Sản phẩm bắt đầu kém chất lượng hơn các lô hàng trước'}],
    answer:'c', why:{a:'Có thể, nhưng khi chỉ một bộ creative chạy lâu thì mỏi creative là giả thuyết cần loại trừ trước.',
      b:'Giá đấu thầu có dao động, nhưng không có căn cứ cho việc “cố tình” với shop nhỏ.',
      c:'Đúng. Chạy một bộ creative 8 tuần thì tần suất tăng, người xem lướt qua — đây là nguyên nhân phổ biến nhất.',
      d:'Chất lượng giảm thường hiện ở đánh giá xấu và hoàn hàng, không phải trước tiên ở chi phí quảng cáo.'} },
  { type:'mcq', stem:'Số liệu: tần suất 4,2, tỉ lệ nhấp giảm gần một nửa, tỉ lệ mua sau nhấp giữ nguyên 3%. Bạn chọn gì?',
    options:[{k:'a',t:'Tắt hẳn chiến dịch, chờ sang mùa sau mới chạy lại từ đầu'},{k:'b',t:'Giữ chiến dịch, thay 2–3 video mới và đo trong một tuần'},
             {k:'c',t:'Giảm giá sản phẩm 20% để kéo tỉ lệ mua sau nhấp lên cao'},{k:'d',t:'Tăng ngân sách gấp đôi để bù lượng đơn đang bị hụt'}],
    answer:'b', why:{a:'Người nhấp vẫn mua tốt; tắt hẳn là bỏ đi một phễu đang chạy chỉ vì mẩu quảng cáo cũ.',
      b:'Đúng. Mô hình này là creative mỏi; thay creative là phép thử rẻ nhất.',
      c:'Tỉ lệ mua sau nhấp không có vấn đề; giảm giá chỉ mỏng lãi.',
      d:'Tăng tiền cho creative đã mỏi thì tần suất càng cao, chi phí càng đắt.'} },
  { type:'calc', stem:'Tỉ lệ nhấp giảm từ 2,0% xuống 1,1%, tỉ lệ mua sau nhấp giữ 3%. Cứ 10.000 lượt hiển thị, số đơn giảm từ bao nhiêu xuống bao nhiêu? Nhập số đơn MẤT ĐI.',
    unit:'đơn', ans:2.7, tol:0.05, wrong:[[0.9,'NHAM_CTR_CVR'],[90,'QUEN_TI_LE_CHUYEN_DOI']], errors:['NHAM_CTR_CVR','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Trước: 10.000 × 2,0% = 200 nhấp × 3% = 6 đơn.','Sau: 10.000 × 1,1% = 110 nhấp × 3% = 3,3 đơn.','Mất đi 6 − 3,3 = <b>2,7 đơn</b>.'] },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy thị trường đã đổi, không chỉ là creative mỏi?',
    options:[{k:'a',t:'Tần suất vượt 4 lần mỗi người trong vòng hai tuần gần nhất'},{k:'b',t:'Bình luận dưới video chủ yếu than phiền đã xem quảng cáo này quá nhiều lần'},
             {k:'c',t:'Tỉ lệ nhấp giảm dần trong khi tỉ lệ mua sau nhấp vẫn ổn định'},{k:'d',t:'Video mới hoàn toàn cũng đắt như cũ, tỉ lệ mua sau nhấp cũng giảm'}],
    answer:'d', why:{a:'Tần suất cao là dấu hiệu mỏi creative điển hình.',
      b:'Người xem chán đúng mẩu quảng cáo — vẫn là mỏi creative.',
      c:'Đây là mô hình mỏi creative: người nhấp vẫn mua như cũ.',
      d:'Đúng. Khi creative mới cũng không cứu được và người nhấp mua ít hơn, vấn đề nằm ngoài mẩu quảng cáo.'} },
  { type:'mcq', stem:'Tình huống mới: một shop áo khoác chạy tốt từ tháng 11 đến tháng 1. Sang tháng 3, mọi creative, kể cả mới làm, đều đắt gấp đôi và người nhấp ít mua. Bạn nên làm gì?',
    options:[{k:'a',t:'Làm thêm 5 video mới vì chắc chắn creative đã mỏi hết rồi'},{k:'b',t:'Thu nhỏ hoặc dừng chiến dịch áo khoác, chuyển tiền sang dòng hợp mùa'},
             {k:'c',t:'Giữ nguyên ngân sách vì chi phí sẽ tự về lại như tháng 12'},{k:'d',t:'Đổi đối tượng sang tỉnh lạnh hơn ở miền Nam cho đủ doanh số'}],
    answer:'b', why:{a:'Creative mới đã thử và cũng đắt — thêm video không đổi được mùa.',
      b:'Đúng. Nhu cầu theo mùa đã qua; đây là thị trường đổi, lý do chính đáng để thu hẹp.',
      c:'Chờ chi phí tự về là đánh cược với mùa vụ, trong lúc tiền vẫn cháy.',
      d:'Miền Nam không có mùa lạnh để bù; nhắm như vậy là không có căn cứ.'} },
  { type:'mcq', stem:'Vì sao tắt cả chiến dịch khi chỉ creative mỏi là một quyết định tốn kém?',
    options:[{k:'a',t:'Vì tắt đi bật lại có thể làm mất phần học của hệ thống và tệp đang tốt'},{k:'b',t:'Vì nền tảng quảng cáo phạt tiền những tài khoản tắt chiến dịch'},
             {k:'c',t:'Vì chi phí đã chi sẽ bị tính lại gấp đôi khi bật chạy lại'},{k:'d',t:'Vì khách cũ sẽ nghĩ thương hiệu sắp phá sản khi thấy dừng'}],
    answer:'a', why:{a:'Đúng. Đối tượng, dữ liệu tối ưu và phễu đang tốt bị bỏ đi, trong khi chỉ cần thay mẩu quảng cáo.',
      b:'Không có khoản phạt như vậy.',
      c:'Tiền đã chi không bị tính lại.',
      d:'Khách hầu như không theo dõi việc bạn tắt bật quảng cáo.'} },
  { type:'mcq', stem:'Cách nào giúp phát hiện creative mỏi sớm nhất?',
    options:[{k:'a',t:'Chờ cuối tháng xem tổng doanh thu có giảm so với tháng trước'},{k:'b',t:'Đọc số lượt thích trên video mỗi tuần một lần vào sáng thứ hai'},
             {k:'c',t:'Theo dõi tần suất và tỉ lệ nhấp theo tuần của từng creative'},{k:'d',t:'Hỏi nhân viên bán hàng xem khách có còn nhắc tới quảng cáo không'}],
    answer:'c', why:{a:'Doanh thu tháng là chỉ số muộn và bị trộn nhiều nguyên nhân.',
      b:'Lượt thích không phản ánh việc người xem có nhấp và mua không.',
      c:'Đúng. Tần suất tăng kèm tỉ lệ nhấp giảm trên từng creative là tín hiệu sớm và rõ.',
      d:'Nhận xét từ nhân viên có ích nhưng chậm và không đo được theo từng creative.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tu06-03', skill:'brand', read:'7 phút', t:'Chiến dịch thương hiệu mới chạy 3 tuần chưa ra đơn — dừng được chưa?',
  situation:'Một hãng nước mắm ở Phan Thiết chạy chiến dịch video kể chuyện làng nghề, mục tiêu là để người nội trợ thành phố nhớ tên. Sau 3 tuần, đơn trên sàn gần như không đổi. Giám đốc bán hàng đòi cắt, chuyển toàn bộ tiền sang quảng cáo giảm giá “vì ra đơn ngay”.',
  concept:{ name:'Nhịp đo của chiến dịch thương hiệu',
    body:'Chiến dịch bán hàng nhắm người đang sẵn mua, nên đơn về trong vài ngày. Chiến dịch thương hiệu nhắm người <b>chưa</b> có nhu cầu hôm nay, để khi họ cần, tên bạn hiện lên trước. Hiệu ứng tích luỹ qua nhiều tháng. Vì vậy không đo nó bằng đơn tuần này, mà bằng chỉ số dẫn trước: tỉ lệ nhớ tên, lượt tìm kiếm tên thương hiệu, số người xem hết video. Điều kiện dừng phải đặt theo đúng nhịp đó: nếu sau thời gian hợp lý mà cả chỉ số dẫn trước cũng không nhúc nhích, lúc đó mới là tín hiệu thật.' },
  example:'Hãng nước mắm xem lại: lượt tìm kiếm tên thương hiệu trên sàn tăng từ 400 lên 1.100 mỗi tuần; khảo sát nhanh 200 người nội trợ, tỉ lệ nhớ tên khi được gợi ý tăng từ 12% lên 21%. Đơn chưa tăng vì một chai nước mắm dùng được vài tuần. Quyết định: giữ chiến dịch thêm 2 tháng, đặt mốc: tìm kiếm tên tiếp tục tăng và đơn từ khách mới tăng ít nhất 15% vào tháng thứ ba.',
  takeaway:'Đo chiến dịch thương hiệu bằng chỉ số dẫn trước và theo nhịp tháng, không bằng đơn tuần.',
  apply:'Chọn một chiến dịch nhận biết bạn từng thấy. Nói trong 60 giây: nếu phải quyết định dừng sau 1 tháng, bạn nhìn chỉ số nào?',
  mistakes:['Đánh giá chiến dịch thương hiệu bằng đơn trong tuần.','Không đặt chỉ số dẫn trước nên không biết khi nào mới thật sự nên dừng.'],
  q:[
  { type:'mcq', stem:'Chiến dịch kể chuyện làng nghề chạy 3 tuần, đơn chưa tăng. Theo bạn, điều này nói lên gì?',
    options:[{k:'a',t:'Chiến dịch thất bại rõ ràng, nên dừng ngay trong tuần này'},{k:'b',t:'Video quá dài, khán giả không đủ kiên nhẫn để xem hết'},
             {k:'c',t:'Chưa kết luận được; cần nhìn chỉ số nhớ tên và tìm kiếm'},{k:'d',t:'Nước mắm là ngành không cần làm thương hiệu, chỉ cần giá rẻ'}],
    answer:'c', why:{a:'Kết luận thất bại dựa trên đơn tuần là dùng sai thước đo cho chiến dịch thương hiệu.',
      b:'Có thể đúng, nhưng chưa có dữ liệu xem hết video để khẳng định.',
      c:'Đúng. Chiến dịch thương hiệu phải đọc qua chỉ số dẫn trước trước khi xét đơn.',
      d:'Hàng tiêu dùng mua lặp lại rất cần được nhớ tên khi khách đứng trước kệ.'} },
  { type:'mcq', stem:'Tìm kiếm tên thương hiệu tăng gần gấp ba, tỉ lệ nhớ tên tăng từ 12% lên 21%, đơn chưa đổi. Giám đốc bán hàng muốn cắt. Bạn đề xuất gì?',
    options:[{k:'a',t:'Cắt ngay, chuyển toàn bộ tiền sang quảng cáo giảm giá theo ý bán hàng'},{k:'b',t:'Giữ, kèm mốc: tìm kiếm tiếp tục tăng và đơn khách mới tăng 15% ở tháng 3'},
             {k:'c',t:'Giữ vô thời hạn vì thương hiệu nào cũng cần ít nhất vài năm mới có kết quả'},{k:'d',t:'Chạy song song cả hai, mỗi bên nửa ngân sách, rồi xem bên nào thắng sau 1 tuần'}],
    answer:'b', why:{a:'Chỉ số dẫn trước đang tốt; cắt lúc này bỏ đi phần đã tích luỹ.',
      b:'Đúng. Giữ nhưng có mốc đo được và hạn cụ thể — không phải niềm tin mù quáng.',
      c:'Không có hạn thì không bao giờ biết khi nào nên dừng.',
      d:'So hai loại chiến dịch sau 1 tuần là đo cả hai bằng thước của chiến dịch bán hàng.'} },
  { type:'calc', stem:'Khảo sát 200 người: tỉ lệ nhớ tên tăng từ 12% lên 21%. Số người nhớ tên trong mẫu tăng thêm bao nhiêu người?',
    unit:'người', ans:18, tol:0.1, wrong:[[9,'NHAM_DIEM_PHAN_TRAM'],[75,'NHAM_TI_LE_ROI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_TI_LE_ROI'],
    steps:['Trước: 200 × 12% = 24 người.','Sau: 200 × 21% = 42 người.','Tăng thêm 42 − 24 = <b>18 người</b>.'] },
  { type:'mcq', stem:'Vì sao chiến dịch bán hàng thường cho kết quả nhanh hơn chiến dịch thương hiệu?',
    options:[{k:'a',t:'Vì chiến dịch bán hàng được nền tảng ưu tiên phân phối trước'},{k:'b',t:'Vì nó nhắm người đang sẵn mua, còn thương hiệu nhắm người mua sau'},
             {k:'c',t:'Vì video thương hiệu luôn dài hơn và tốn nhiều tiền sản xuất hơn'},{k:'d',t:'Vì người xem tin quảng cáo giảm giá hơn tin câu chuyện thương hiệu'}],
    answer:'b', why:{a:'Nền tảng phân phối theo mục tiêu bạn chọn, không ưu tiên loại chiến dịch.',
      b:'Đúng. Khác biệt nằm ở đối tượng: người sẵn mua mua ngay, người chưa cần thì mua khi nhu cầu đến.',
      c:'Độ dài và chi phí sản xuất không quyết định tốc độ ra kết quả.',
      d:'Niềm tin không phải lý do; khác biệt là thời điểm nhu cầu.'} },
  { type:'mcq', stem:'Tình huống mới: một thương hiệu nệm chạy chiến dịch nhận biết 4 tháng. Tìm kiếm tên, lượt xem hết video và tỉ lệ nhớ tên đều đứng yên từ tháng thứ hai. Bạn nên làm gì?',
    options:[{k:'a',t:'Chờ thêm vì nệm là hàng vài năm mới mua một lần, cần thật kiên nhẫn'},{k:'b',t:'Tăng tần suất gấp đôi để khán giả nhớ tên nhanh hơn nữa'},
             {k:'c',t:'Chuyển thẳng sang chạy giảm giá vì thương hiệu vốn không hiệu quả'},{k:'d',t:'Dừng hoặc làm lại chiến dịch vì chính chỉ số dẫn trước không nhích'}],
    answer:'d', why:{a:'Chu kỳ mua dài giải thích đơn chậm, không giải thích việc chỉ số dẫn trước đứng yên.',
      b:'Nếu thông điệp không ghi nhớ được, lặp nhiều hơn chỉ tốn thêm.',
      c:'Một chiến dịch thương hiệu hỏng không chứng minh mọi chiến dịch thương hiệu vô ích.',
      d:'Đúng. Khi chính thước đo phù hợp nhịp của nó cũng không nhúc nhích, đó là tín hiệu dừng thật.'} },
  { type:'mcq', stem:'Chỉ số nào KHÔNG phù hợp để đánh giá chiến dịch thương hiệu sau một tháng?',
    options:[{k:'a',t:'Tỉ lệ nhớ tên khi được gợi ý qua khảo sát ngắn'},{k:'b',t:'Lượt tìm kiếm tên thương hiệu trên sàn và công cụ tìm kiếm'},
             {k:'c',t:'Số đơn trả tiền trong 7 ngày sau khi người dùng xem quảng cáo'},{k:'d',t:'Tỉ lệ người xem hết video trên tổng lượt hiển thị'}],
    answer:'c', why:{a:'Đo trực tiếp việc được nhớ — mục tiêu của chiến dịch.',
      b:'Người tự tìm tên là dấu hiệu tên đã vào trí nhớ.',
      c:'Đúng. Đơn trong 7 ngày là thước đo của chiến dịch bán hàng, bỏ qua phần lớn tác động dài hạn.',
      d:'Xem hết cho biết thông điệp có được tiếp nhận không.'} },
  { type:'mcq', stem:'Cách đặt điều kiện dừng cho chiến dịch thương hiệu nào hợp lý nhất?',
    options:[{k:'a',t:'Dừng nếu sau 3 tháng tìm kiếm tên và nhớ tên không tăng'},{k:'b',t:'Dừng nếu bất kỳ tuần nào chi phí mỗi đơn cao hơn tuần trước'},
             {k:'c',t:'Dừng khi giám đốc cảm thấy quảng cáo không còn thấy nhiều'},{k:'d',t:'Không đặt điều kiện dừng vì thương hiệu là khoản đầu tư dài hạn'}],
    answer:'a', why:{a:'Đúng. Chỉ số đúng loại, hạn đúng nhịp, đo được.',
      b:'Chi phí mỗi đơn theo tuần là thước đo sai nhịp và sai loại.',
      c:'Cảm giác của người trong công ty không phản ánh khách hàng.',
      d:'Không có điều kiện dừng thì chiến dịch hỏng vẫn chạy mãi.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tu06-04', skill:'measure', read:'6 phút', t:'Tắt một phát hay giảm dần ngân sách?',
  situation:'Một thương hiệu đồ ăn vặt chạy chiến dịch 12 triệu/ngày. Hai tuần gần đây lãi biên giảm dần nhưng vẫn còn dương ở phần ngân sách đầu, còn phần cuối thì lỗ. Quản lý phân vân giữa tắt ngay toàn bộ hay cắt từng nấc.',
  concept:{ name:'Dừng hẳn và giảm dần',
    body:'Mỗi đồng thêm vào chiến dịch thường kém hiệu quả hơn đồng trước, vì hệ thống phải với tới người ít quan tâm hơn. Nên một chiến dịch có thể <b>lãi ở mức chi thấp và lỗ ở mức chi cao</b>. Khi đó giảm dần là hợp lý: cắt phần lỗ, giữ phần lãi, và mỗi nấc cắt khoảng 20–30% để hệ thống ổn định lại rồi đo. Dừng hẳn hợp lý khi ngay cả phần hiệu quả nhất cũng lỗ, khi có rủi ro thương hiệu, hoặc khi sản phẩm hết hàng.' },
  example:'Tách số liệu theo mức chi: ở 6 triệu/ngày đầu, mỗi ngày lãi sau quảng cáo 2 triệu; 6 triệu sau chỉ về lãi gộp 4,5 triệu, tức lỗ 1,5 triệu. Tổng mỗi ngày lãi 0,5 triệu. Tắt hết là mất 2 triệu lãi. Giảm về 8 triệu, đo 3 ngày, rồi về 6 triệu nếu cần — mỗi ngày giữ được gần 2 triệu thay vì 0,5 triệu.',
  takeaway:'Nếu phần đầu còn lãi, cắt phần lỗ bằng các nấc nhỏ; chỉ dừng hẳn khi cả phần tốt nhất cũng lỗ.',
  apply:'Nói trong 60 giây: với một chiến dịch bạn biết, nếu cắt nửa ngân sách, bạn đoán phần mất đi là phần lãi hay phần lỗ?',
  mistakes:['Tắt toàn bộ khi chỉ phần chi thêm là lỗ.','Cắt 80% một lần khiến hệ thống phân phối chao đảo, không đọc được số.'],
  q:[
  { type:'mcq', stem:'Chiến dịch lãi ở 6 triệu đầu, lỗ ở 6 triệu sau. Theo bạn, cách xử lý tự nhiên nhất là gì?',
    options:[{k:'a',t:'Tắt toàn bộ vì tổng thể lãi quá mỏng, không đáng công theo dõi'},{k:'b',t:'Giữ 12 triệu và đổi creative để phần sau cũng có lãi'},
             {k:'c',t:'Tăng lên 15 triệu để hệ thống học nhanh hơn và rẻ đi'},{k:'d',t:'Giảm dần về gần mức còn lãi, đo lại sau mỗi nấc'}],
    answer:'d', why:{a:'Tắt hết là bỏ luôn phần lãi 2 triệu mỗi ngày.',
      b:'Đổi creative có thể giúp, nhưng trong lúc chờ vẫn lỗ ở phần chi sau.',
      c:'Chi thêm thường với tới người kém quan tâm hơn, lỗ sẽ sâu hơn.',
      d:'Đúng. Cắt phần lỗ, giữ phần lãi, từng nấc để đọc được số.'} },
  { type:'mcq', stem:'Bạn quyết định giảm. Cách cắt nào bạn chọn?',
    options:[{k:'a',t:'Cắt thẳng từ 12 xuống 2 triệu ngay trong một lần cho nhanh'},{k:'b',t:'Cắt về 8 triệu, đo 3 ngày, rồi về 6 triệu nếu vẫn lỗ phần cuối'},
             {k:'c',t:'Tắt 3 ngày rồi bật lại ở 6 triệu để hệ thống làm lại từ đầu'},{k:'d',t:'Giữ ngân sách nhưng thu hẹp đối tượng còn một tỉnh duy nhất'}],
    answer:'b', why:{a:'Cắt quá mạnh làm hệ thống phân phối chao đảo, và bạn cắt cả phần lãi.',
      b:'Đúng. Mỗi nấc khoảng 20–30%, đo đủ ngày để thấy tác động thật.',
      c:'Tắt rồi bật lại dễ mất phần học của hệ thống, không cần thiết.',
      d:'Thu hẹp đối tượng mạnh mà giữ tiền làm tần suất tăng vọt và chi phí đắt thêm.'} },
  { type:'calc', stem:'Ở 12 triệu/ngày, chiến dịch lãi 0,5 triệu/ngày. Ở 6 triệu/ngày, lãi 2 triệu/ngày. Nếu giảm về 6 triệu và giữ 20 ngày, bạn có thêm bao nhiêu triệu lãi so với giữ 12 triệu?',
    unit:'triệu đồng', ans:30, tol:0.5, wrong:[[40,'NHAM_SO_TUYET_DOI'],[10,'SAI_TINH_TOAN']], errors:['NHAM_SO_TUYET_DOI','SAI_TINH_TOAN'],
    steps:['Chênh lệch mỗi ngày: 2 − 0,5 = 1,5 triệu.','20 ngày: 1,5 × 20 = <b>30 triệu</b>.'] },
  { type:'mcq', stem:'Trường hợp nào nên dừng hẳn ngay thay vì giảm dần?',
    options:[{k:'a',t:'Lãi biên của phần chi cuối cùng vừa chuyển sang âm nhẹ'},{k:'b',t:'Chi phí mỗi đơn tăng 10% so với tuần trước do vào mùa cao điểm'},
             {k:'c',t:'Sản phẩm đang quảng cáo vừa hết hàng, 2 tuần nữa mới về'},{k:'d',t:'Đối thủ vừa tung một chiến dịch lớn cùng khung giờ với bạn'}],
    answer:'c', why:{a:'Chỉ phần cuối âm là tình huống điển hình để giảm dần.',
      b:'Tăng nhẹ theo mùa là lý do xem lại, không phải tắt hết.',
      c:'Đúng. Hết hàng thì mọi đồng chi đều không ra đơn và còn làm khách bực.',
      d:'Đối thủ chạy mạnh làm chi phí tăng; đo tác động rồi điều chỉnh, chưa phải lý do dừng.'} },
  { type:'mcq', stem:'Vì sao đồng quảng cáo thêm thường kém hiệu quả hơn đồng trước?',
    options:[{k:'a',t:'Hệ thống phải với tới những người ít quan tâm hơn'},{k:'b',t:'Nền tảng thu phí cao hơn với tài khoản chi nhiều tiền'},
             {k:'c',t:'Người xem bắt đầu chặn quảng cáo khi thấy thương hiệu chi nhiều'},{k:'d',t:'Ngân sách lớn làm video bị nén chất lượng thấp khi hiển thị'}],
    answer:'a', why:{a:'Đúng. Người dễ mua nhất được với tới trước; phần sau là người khó hơn.',
      b:'Không có cơ chế tính giá theo mức chi như vậy.',
      c:'Người xem không biết bạn chi bao nhiêu.',
      d:'Chất lượng hiển thị không phụ thuộc ngân sách.'} },
  { type:'mcq', stem:'Tình huống mới: một spa chạy 5 triệu/ngày, tách số cho thấy cả 2 triệu đầu tiên — phần hiệu quả nhất — cũng lỗ. Bạn chọn gì?',
    options:[{k:'a',t:'Giảm về 2 triệu và giữ, vì đó là phần tốt nhất của chiến dịch'},{k:'b',t:'Giảm dần mỗi tuần 10% cho đến khi hết ngân sách của tháng'},
             {k:'c',t:'Tăng lên 8 triệu để hệ thống có đủ dữ liệu tối ưu tốt hơn'},{k:'d',t:'Dừng và xem lại ưu đãi, trang đặt lịch trước khi chạy lại'}],
    answer:'d', why:{a:'Phần tốt nhất cũng lỗ thì giữ nó vẫn là lỗ.',
      b:'Giảm dần chỉ kéo dài thời gian lỗ.',
      c:'Không có dấu hiệu nào cho thấy chi thêm sẽ đảo chiều.',
      d:'Đúng. Khi phần hiệu quả nhất cũng lỗ, vấn đề nằm ở gốc — ưu đãi, trang, sản phẩm.'} },
  { type:'mcq', stem:'Sau khi cắt một nấc ngân sách, bạn nên chờ bao lâu trước khi đọc số?',
    options:[{k:'a',t:'Vài giờ, vì hệ thống quảng cáo phản ứng ngay lập tức với thay đổi'},{k:'b',t:'Đủ vài ngày để hệ thống ổn định và có đủ đơn để so'},
             {k:'c',t:'Ít nhất hai tháng để có đủ dữ liệu theo đúng chu kỳ mùa'},{k:'d',t:'Không cần chờ, cứ cắt tiếp đến khi chi phí mỗi đơn giảm hẳn'}],
    answer:'b', why:{a:'Vài giờ quá ít đơn và hệ thống chưa ổn định lại.',
      b:'Đúng. Vài ngày đủ để phân phối ổn định và đủ số đơn để so.',
      c:'Hai tháng là quá lâu cho một thay đổi ngân sách; bạn lỗ trong lúc chờ.',
      d:'Cắt liên tục không đo sẽ không biết nấc nào là đủ.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tu06-05', skill:'comm', read:'7 phút', t:'Bão lũ đang xảy ra, chiến dịch vui nhộn có nên tạm dừng?',
  situation:'Một hãng đồ uống đang chạy chiến dịch “Sảng khoái cuối tuần” với video nhảy nhót và mã giảm giá. Cuối tuần đó bão lớn đổ bộ miền Trung, nhiều địa phương ngập nặng, mạng xã hội tràn tin cứu trợ. Quảng cáo vẫn đang chạy toàn quốc, kể cả vùng bị ảnh hưởng.',
  concept:{ name:'Tạm dừng khi có khủng hoảng xã hội',
    body:'Khi xã hội có biến cố lớn — thiên tai, tai nạn thảm khốc, tang lễ quốc gia — một quảng cáo vui nhộn đặt cạnh tin đau buồn dễ bị xem là vô cảm, dù không có ý xấu. Nguyên tắc: <b>tạm dừng trước, đánh giá sau</b>. Rà các quảng cáo và bài đăng lên lịch sẵn, dừng nội dung có giọng vui, khuyến mãi, hoặc từ ngữ dễ gợi liên tưởng xấu. Không biến thảm hoạ thành dịp quảng bá. Nếu hỗ trợ, làm thật và nói ít. Khi quay lại, chọn thời điểm dư luận đã lắng và giọng nhẹ nhàng hơn.' },
  example:'Hãng đồ uống dừng tất cả quảng cáo có mã giảm giá và video nhảy trong 5 ngày, huỷ 3 bài đăng hẹn giờ. Họ chuyển hàng nước uống tới điểm tiếp nhận cứu trợ qua hội chữ thập đỏ địa phương, chỉ đăng một bài ngắn xác nhận, không kèm logo lớn. Tuần sau, khi tin tức chuyển sang phục hồi, họ chạy lại chiến dịch ở các tỉnh không bị ảnh hưởng trước, rồi mới mở rộng.',
  takeaway:'Khi xã hội có biến cố, tạm dừng nội dung vui trước; hỗ trợ thì làm thật, nói ít.',
  apply:'Mở lịch đăng bài của một thương hiệu bạn theo dõi. Nói trong 60 giây: nếu có thiên tai sáng mai, bài nào phải gỡ đầu tiên?',
  mistakes:['Quên các bài hẹn giờ và quảng cáo đang chạy tự động.','Đăng hình ảnh cứu trợ kèm logo to như một chiến dịch quảng bá.'],
  q:[
  { type:'mcq', stem:'Bão đang gây ngập nặng, quảng cáo nhảy nhót có mã giảm giá vẫn chạy toàn quốc. Rủi ro lớn nhất là gì?',
    options:[{k:'a',t:'Chi phí quảng cáo tăng vì mọi người lên mạng xem tin bão nhiều hơn'},{k:'b',t:'Thương hiệu bị xem là vô cảm khi quảng cáo vui nằm cạnh tin đau buồn'},
             {k:'c',t:'Mã giảm giá bị dùng quá nhiều vì người dân tích trữ đồ uống'},{k:'d',t:'Quảng cáo đã duyệt đúng quy định thì cứ chạy, khách tự phân biệt được'}],
    answer:'b', why:{a:'Chi phí có thể dao động, nhưng không phải rủi ro chính.',
      b:'Đúng. Rủi ro là cảm nhận của công chúng về thái độ thương hiệu.',
      c:'Không có căn cứ; và đó không phải mối lo chính.',
      d:'Được duyệt nội dung không có nghĩa là phù hợp với bối cảnh lúc này.'} },
  { type:'mcq', stem:'Bạn là người phụ trách chiến dịch, thấy tin bão sáng thứ bảy. Việc đầu tiên bạn làm là gì?',
    options:[{k:'a',t:'Chờ đến thứ hai họp cả nhóm rồi quyết định cho đủ ý kiến'},{k:'b',t:'Chỉ tắt quảng cáo ở vùng bão, giữ nguyên ở các tỉnh còn lại'},
             {k:'c',t:'Tạm dừng các quảng cáo và bài hẹn giờ có giọng vui, khuyến mãi'},{k:'d',t:'Đổi video thành hình ảnh cứu trợ có logo thương hiệu to rõ ràng'}],
    answer:'c', why:{a:'Chờ 2 ngày là để nội dung vui chạy suốt lúc cao điểm của tin tức.',
      b:'Cả nước đang theo dõi tin bão; người ở tỉnh khác cũng thấy sự lạc lõng.',
      c:'Đúng. Tạm dừng trước, đánh giá sau — gồm cả bài hẹn giờ dễ bị quên.',
      d:'Gắn logo lên hình ảnh cứu trợ dễ bị xem là lợi dụng thảm hoạ.'} },
  { type:'mcq', stem:'Nếu thương hiệu muốn hỗ trợ vùng bão, cách nào phù hợp nhất?',
    options:[{k:'a',t:'Chạy quảng cáo “mua một chai, góp một chai” trong lúc bão đang diễn ra'},{k:'b',t:'Quay video trao quà có đại sứ thương hiệu và phát trên mọi kênh quảng cáo'},
             {k:'c',t:'Treo băng rôn thương hiệu lớn ở điểm phát quà để mọi người ghi nhận'},{k:'d',t:'Chuyển hàng qua tổ chức cứu trợ và đăng một bài ngắn xác nhận'}],
    answer:'d', why:{a:'Gắn việc hỗ trợ vào doanh số khi thảm hoạ đang diễn ra dễ gây phản cảm.',
      b:'Biến hỗ trợ thành nội dung quảng cáo trả tiền là lợi dụng.',
      c:'Băng rôn lớn ở điểm cứu trợ biến người khó khăn thành phông nền quảng bá.',
      d:'Đúng. Làm thật qua kênh đáng tin, nói ít và không đặt thương hiệu lên trung tâm.'} },
  { type:'mcq', stem:'Khi nào nên cho chiến dịch chạy lại?',
    options:[{k:'a',t:'Ngay khi bão tan, vì khách hàng cần niềm vui để vượt qua'},{k:'b',t:'Khi tin tức đã chuyển sang phục hồi, bắt đầu ở vùng không bị ảnh hưởng'},
             {k:'c',t:'Sau đúng một tháng, bất kể tình hình ở vùng bị ảnh hưởng ra sao'},{k:'d',t:'Không bao giờ; chiến dịch gắn với cơn bão rồi nên phải bỏ hẳn'}],
    answer:'b', why:{a:'Bão tan nhưng hậu quả vẫn là tin chính; “niềm vui” lúc này dễ lạc lõng.',
      b:'Đúng. Chọn thời điểm dư luận đã lắng và mở dần từ vùng ít nhạy cảm.',
      c:'Một mốc cứng không nhìn tới bối cảnh thực tế.',
      d:'Chiến dịch không có lỗi; chỉ thời điểm không phù hợp.'} },
  { type:'mcq', stem:'Tình huống mới: một chuỗi đồ nướng có sẵn bài hẹn giờ “Cháy hết mình cuối tuần!” đúng hôm có vụ cháy nhà dân gây thương vong được cả nước quan tâm. Bạn làm gì?',
    options:[{k:'a',t:'Gỡ bài hẹn giờ ngay, rà các nội dung có từ ngữ liên quan lửa, cháy'},{k:'b',t:'Giữ bài vì nội dung nói về đồ nướng, không liên quan vụ việc'},
             {k:'c',t:'Sửa câu thành “Cháy cùng bạn bè” cho bớt mạnh rồi đăng như cũ'},{k:'d',t:'Đăng lời chia buồn kèm mã giảm giá để thể hiện sự quan tâm'}],
    answer:'a', why:{a:'Đúng. Từ ngữ vô tình gợi liên tưởng tới thảm kịch cần gỡ ngay, kể cả khi ý định vô hại.',
      b:'Người đọc không đọc ý định, họ đọc chữ “cháy” cạnh tin thương vong.',
      c:'Vẫn dùng đúng từ nhạy cảm; sửa nhẹ không giải quyết vấn đề.',
      d:'Gắn khuyến mãi vào lời chia buồn là phản cảm.'} },
  { type:'mcq', stem:'Vì sao cần rà cả các bài hẹn giờ, không chỉ quảng cáo đang chạy?',
    options:[{k:'a',t:'Vì bài hẹn giờ tự đăng dù không ai trong team đang để ý'},{k:'b',t:'Vì bài hẹn giờ tốn nhiều tiền hơn quảng cáo đang chạy'},
             {k:'c',t:'Vì nền tảng ưu tiên phân phối bài hẹn giờ lúc có sự kiện lớn'},{k:'d',t:'Vì bài hẹn giờ không thể xoá sau khi đã đăng lên trang'}],
    answer:'a', why:{a:'Đúng. Lỗi hay gặp nhất là bài lên lịch từ tuần trước tự đăng giữa lúc tang thương.',
      b:'Bài hẹn giờ thường không tốn tiền; vấn đề là nội dung.',
      c:'Không có cơ chế ưu tiên như vậy.',
      d:'Có thể xoá, nhưng khi đó người ta đã chụp màn hình.'} },
  { type:'mcq', stem:'Điều nào nên chuẩn bị TRƯỚC khi có khủng hoảng xã hội?',
    options:[{k:'a',t:'Soạn sẵn mẫu bài quảng bá gắn với các loại thiên tai thường gặp'},{k:'b',t:'Giao việc theo dõi tin tức cho đại lý và không cần quy trình nội bộ'},
             {k:'c',t:'Một danh sách ai có quyền tạm dừng mọi kênh và cách làm trong 1 giờ'},{k:'d',t:'Mua sẵn quảng cáo khung giờ vàng để không bị đối thủ chiếm chỗ'}],
    answer:'c', why:{a:'Soạn sẵn bài quảng bá gắn thiên tai là chuẩn bị để lợi dụng.',
      b:'Không có quy trình nội bộ thì khi có chuyện không ai biết ai bấm dừng.',
      c:'Đúng. Khi có biến cố, tốc độ tạm dừng quan trọng nhất; phải biết trước ai làm và làm thế nào.',
      d:'Không liên quan tới việc phản ứng đúng khi có biến cố.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tu06-06', skill:'measure', read:'6 phút', t:'Đạt mục tiêu sau 2 tuần thay vì 4 — dừng hay chạy nốt?',
  situation:'Một trung tâm tiếng Anh ở Cần Thơ chạy chiến dịch tuyển sinh khoá hè, mục tiêu 120 học viên, ngân sách 60 triệu cho 4 tuần. Sau 2 tuần đã có 125 đăng ký, mới tiêu 28 triệu. Lớp chỉ có 130 chỗ. Nhân viên đề nghị “chạy nốt cho hết ngân sách đã duyệt”.',
  concept:{ name:'Dừng khi đạt mục tiêu sớm',
    body:'Ngân sách là <b>mức trần</b>, không phải chỉ tiêu phải tiêu hết. Khi mục tiêu đã đạt, hỏi: còn năng lực phục vụ thêm không? Nếu hết chỗ, hết hàng hay đội chăm sóc quá tải, đồng tiền tiếp theo chỉ tạo khách bị từ chối hoặc phục vụ kém. Lúc đó nên dừng, hoặc chuyển sang mục tiêu khác có ích: thu danh sách chờ khoá sau, hay chuyển tiền sang sản phẩm còn năng lực. Tiền tiết kiệm được ghi lại như kết quả, kèm bài học vì sao chiến dịch vượt dự kiến.' },
  example:'Trung tâm còn 5 chỗ. Chạy thêm 32 triệu theo nhịp hiện tại sẽ mang về khoảng 140 đăng ký nữa, tức 135 người bị từ chối — tốn tiền và làm họ bực. Họ dừng quảng cáo tuyển sinh, chuyển 5 triệu sang thu danh sách chờ khoá thu, giữ lại 27 triệu. Báo cáo: đạt 104% mục tiêu với 47% ngân sách, và ghi rõ lý do — ưu đãi đăng ký nhóm hiệu quả hơn dự kiến.',
  takeaway:'Ngân sách là trần, không phải chỉ tiêu; hết năng lực phục vụ thì dừng hoặc đổi mục tiêu.',
  apply:'Nói trong 60 giây: nếu chiến dịch của bạn đạt mục tiêu sớm một nửa thời gian, bạn dùng phần tiền còn lại thế nào?',
  mistakes:['Tiêu hết ngân sách vì sợ bị cắt ngân sách kỳ sau.','Tiếp tục thu khách khi không còn chỗ, hàng hay người phục vụ.'],
  q:[
  { type:'mcq', stem:'Đạt 125/120 đăng ký sau nửa thời gian, lớp còn 5 chỗ. Theo bạn, ngân sách còn lại nên hiểu thế nào?',
    options:[{k:'a',t:'Là tiền đã được duyệt nên phải tiêu hết đúng như kế hoạch'},{k:'b',t:'Là mức trần; không cần tiêu nếu không tạo thêm giá trị'},
             {k:'c',t:'Là tiền thưởng cho team vì chiến dịch đã vượt mục tiêu'},{k:'d',t:'Là khoản nên chuyển ngay vào quảng cáo thương hiệu để khỏi lãng phí'}],
    answer:'b', why:{a:'Tiêu hết khi không cần là đốt tiền vì thói quen.',
      b:'Đúng. Ngân sách giới hạn mức chi tối đa, không bắt buộc chi.',
      c:'Ngân sách quảng cáo không phải quỹ thưởng.',
      d:'Chuyển vội sang mục tiêu khác không có kế hoạch cũng là lãng phí.'} },
  { type:'mcq', stem:'Nhân viên muốn “chạy nốt cho hết ngân sách”. Bạn chọn gì?',
    options:[{k:'a',t:'Chạy nốt nhưng giảm một nửa để vừa đủ cho 5 chỗ còn lại'},{k:'b',t:'Chạy nốt để có thêm dữ liệu cho báo cáo cuối năm đẹp hơn'},
             {k:'c',t:'Tăng học phí khoá hè và chạy tiếp cho hết ngân sách đã duyệt'},{k:'d',t:'Dừng tuyển sinh, dùng ít tiền thu danh sách chờ khoá sau'}],
    answer:'d', why:{a:'Một nửa ngân sách vẫn mang về gấp nhiều lần 5 chỗ còn lại.',
      b:'Số đăng ký không có chỗ là dữ liệu đắt và làm khách thất vọng.',
      c:'Tăng giá giữa chừng khi người khác đã đăng ký giá cũ dễ gây bất bình.',
      d:'Đúng. Hết năng lực thì dừng, và chuyển phần nhỏ sang mục tiêu có ích cho khoá sau.'} },
  { type:'calc', stem:'Chiến dịch đạt 125 đăng ký với 28 triệu. Ngân sách 60 triệu. Nếu dừng, phần trăm ngân sách đã dùng là bao nhiêu?',
    unit:'%', ans:46.7, tol:0.2, wrong:[[53.3,'SAI_MAU_SO'],[214.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Phần trăm đã dùng = đã tiêu ÷ ngân sách.','28 ÷ 60 = 0,467 ≈ <b>46,7%</b>.'] },
  { type:'mcq', stem:'Khi báo cáo chiến dịch đạt mục tiêu sớm, điều gì quan trọng nhất cần ghi lại?',
    options:[{k:'a',t:'Lý do chiến dịch vượt dự kiến, để lặp lại được lần sau'},{k:'b',t:'Lời khen của sếp và tên người phụ trách chiến dịch này'},
             {k:'c',t:'Số tiền tiết kiệm được, để xin tăng lương cho cả nhóm'},{k:'d',t:'Ảnh chụp màn hình quảng cáo đẹp nhất để làm hồ sơ năng lực'}],
    answer:'a', why:{a:'Đúng. Hiểu vì sao tốt hơn dự kiến mới là tài sản cho lần sau.',
      b:'Ghi công có thể có, nhưng không giúp chiến dịch sau tốt hơn.',
      c:'Tiền tiết kiệm nên ghi lại, nhưng không phải để xin lương.',
      d:'Ảnh quảng cáo không giải thích vì sao đạt kết quả.'} },
  { type:'mcq', stem:'Tình huống mới: một shop bánh trung thu đạt 100% chỉ tiêu 800 hộp sau 10 ngày, xưởng chỉ làm thêm được 150 hộp nữa. Chiến dịch còn 20 ngày. Bạn làm gì?',
    options:[{k:'a',t:'Chạy tiếp đủ 20 ngày, hết hàng thì nhận đặt trước khách vẫn chờ'},{k:'b',t:'Tăng ngân sách vì đang bán chạy, sẽ tìm xưởng khác làm thêm'},
             {k:'c',t:'Giảm mạnh ngân sách, nhắm đủ 150 hộp rồi dừng hẳn'},{k:'d',t:'Giữ nguyên ngân sách nhưng tăng giá để bớt người đặt'}],
    answer:'c', why:{a:'Bánh trung thu có hạn theo mùa; nhận đặt mà không giao kịp là mất uy tín.',
      b:'Tìm xưởng khác giữa mùa rủi ro chất lượng và không chắc làm kịp.',
      c:'Đúng. Chi vừa đủ để bán hết năng lực còn lại, không hơn.',
      d:'Tăng giá giữa chừng có thể làm khách cũ phật lòng, và vẫn tốn tiền quảng cáo.'} },
  { type:'mcq', stem:'Vì sao nhiều người vẫn tiêu hết ngân sách dù đã đạt mục tiêu?',
    options:[{k:'a',t:'Vì hệ thống quảng cáo không cho dừng trước hạn đã đặt'},{k:'b',t:'Vì sợ kỳ sau bị cắt ngân sách nếu kỳ này tiêu không hết'},
             {k:'c',t:'Vì tiêu hết ngân sách luôn giúp chi phí mỗi đơn giảm xuống'},{k:'d',t:'Vì luật yêu cầu doanh nghiệp tiêu đúng ngân sách đã duyệt'}],
    answer:'b', why:{a:'Có thể dừng bất cứ lúc nào.',
      b:'Đúng. Đây là động cơ phổ biến; cách giải là báo cáo tiền tiết kiệm như một kết quả.',
      c:'Chi thêm thường làm chi phí mỗi đơn tăng, không giảm.',
      d:'Không có yêu cầu như vậy với ngân sách marketing nội bộ.'} },
  { type:'mcq', stem:'Khi nào đạt mục tiêu sớm mà vẫn nên chạy tiếp?',
    options:[{k:'a',t:'Khi mục tiêu ban đầu đặt quá thấp so với khả năng thực tế của team'},{k:'b',t:'Khi đội bán hàng muốn có thêm khách để đạt chỉ tiêu riêng của họ'},
             {k:'c',t:'Khi còn năng lực phục vụ và mỗi đơn thêm vẫn có lãi biên dương'},{k:'d',t:'Khi đối thủ đang chạy mạnh và mình muốn giữ thị phần hiển thị'}],
    answer:'c', why:{a:'Mục tiêu thấp là bài học cho lần sau; quyết định chạy tiếp vẫn phải dựa vào năng lực và lãi.',
      b:'Chỉ tiêu riêng không phải căn cứ nếu không phục vụ được khách.',
      c:'Đúng. Còn chỗ và còn lãi thì mục tiêu cũ không phải lý do dừng.',
      d:'Giữ hiển thị khi không phục vụ được thêm khách là chi cho ai?'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tu06-07', skill:'comm', read:'7 phút', t:'Muốn dừng chiến dịch nhưng đã ký hợp đồng với KOL?',
  situation:'Một thương hiệu serum ký hợp đồng với một KOL làm đẹp: 4 video trong 2 tháng, tổng 80 triệu, đã trả trước 40 triệu. Sau video thứ 2, số đơn từ mã giảm giá riêng của KOL rất thấp. Thương hiệu muốn dừng, nhưng hợp đồng chưa có điều khoản chấm dứt sớm rõ ràng.',
  concept:{ name:'Dừng khi có cam kết với đối tác',
    body:'Hợp đồng là lời hứa; dừng đơn phương làm mất uy tín trong giới KOL và đối tác, và có thể phát sinh bồi thường. Trước khi quyết, hãy tách: phần nào <b>đã cam kết</b> không lấy lại được, phần nào còn <b>thương lượng</b> được. Thường có ba hướng: làm nốt nhưng đổi nội dung cho phù hợp hơn; chuyển phần còn lại sang hình thức khác (bài đăng, livestream); hoặc thoả thuận chấm dứt có bồi hoàn một phần. Nói chuyện sớm và thẳng với đối tác. Bài học cho lần sau: ghi điều khoản chấm dứt và chia hợp đồng theo từng đợt.' },
  example:'Thương hiệu gặp KOL, chia sẻ số liệu thật mà không trách móc. Họ đề xuất: video 3 đổi sang dạng hướng dẫn dùng serum kèm routine ban đêm — nội dung KOL đó vốn có người xem hết cao; video 4 chuyển thành một buổi livestream có quà. Nếu sau video 3 đơn vẫn dưới mốc đã thống nhất, hai bên dừng, thương hiệu trả thêm 15 triệu cho công chuẩn bị. Tổng chi tối đa 55 triệu thay vì 80 triệu, quan hệ vẫn giữ.',
  takeaway:'Có hợp đồng thì thương lượng chứ không bỏ ngang; lần sau ghi sẵn điều khoản dừng.',
  apply:'Nói trong 60 giây: nếu phải báo một đối tác rằng bạn muốn dừng, câu mở đầu bạn dùng là gì?',
  mistakes:['Im lặng không trả phần còn lại, để đối tác tự hiểu.','Ký một hợp đồng lớn trọn gói mà không có mốc đánh giá hay điều khoản dừng.'],
  q:[
  { type:'mcq', stem:'Hợp đồng KOL chưa có điều khoản chấm dứt sớm, kết quả kém. Theo bạn, rủi ro lớn nhất nếu thương hiệu tự ý ngừng là gì?',
    options:[{k:'a',t:'KOL sẽ đăng video chê sản phẩm để trả đũa ngay lập tức'},{k:'b',t:'Chẳng sao, vì kết quả kém là lỗi của KOL nên thương hiệu có quyền dừng'},
             {k:'c',t:'Mất uy tín với đối tác và có thể phải bồi thường theo hợp đồng'},{k:'d',t:'Nền tảng mạng xã hội sẽ khoá tài khoản quảng cáo của thương hiệu'}],
    answer:'c', why:{a:'Có thể có phản ứng, nhưng đó là giả định; rủi ro chắc chắn là uy tín và pháp lý.',
      b:'Hợp đồng thường cam kết số video, không cam kết số đơn; kết quả kém không tự cho quyền dừng.',
      c:'Đúng. Bỏ ngang một cam kết đã ký gây thiệt cả về quan hệ lẫn nghĩa vụ hợp đồng.',
      d:'Nền tảng không can thiệp vào hợp đồng giữa hai bên.'} },
  { type:'mcq', stem:'Bạn phụ trách mối quan hệ với KOL này. Bạn làm gì?',
    options:[{k:'a',t:'Gặp KOL, chia sẻ số liệu, đề xuất đổi nội dung và mốc dừng hai bên cùng chấp nhận'},{k:'b',t:'Gửi email ngắn báo dừng, giữ lại 40 triệu còn lại và không giải thích gì'},
             {k:'c',t:'Làm nốt 2 video như hợp đồng cũ, không cần thay đổi gì'},{k:'d',t:'Nhờ luật sư gửi văn bản yêu cầu KOL hoàn lại tiền đã trả trước'}],
    answer:'a', why:{a:'Đúng. Minh bạch số liệu, đề xuất phương án cụ thể và mốc rõ giúp giảm lỗ mà giữ quan hệ.',
      b:'Bỏ ngang làm mất uy tín và có thể vi phạm hợp đồng.',
      c:'Làm nốt không đổi gì là chấp nhận lỗ khi còn chỗ để thương lượng.',
      d:'Đòi hoàn tiền khi KOL đã làm đúng phần việc là không có căn cứ và phá quan hệ.'} },
  { type:'calc', stem:'Hợp đồng 80 triệu, đã trả 40 triệu. Thoả thuận mới: làm thêm 1 video, nếu không đạt mốc thì dừng và trả thêm 15 triệu. Tổng chi tối đa là bao nhiêu triệu?',
    unit:'triệu đồng', ans:55, tol:0.1, wrong:[[15,'SAI_TINH_TOAN'],[95,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Đã trả: 40 triệu.','Trả thêm theo thoả thuận: 15 triệu.','Tổng tối đa: 40 + 15 = <b>55 triệu</b>.'] },
  { type:'mcq', stem:'Cách thiết kế hợp đồng nào giúp lần sau dễ dừng hơn?',
    options:[{k:'a',t:'Trả trước 100% để được giá tốt và KOL làm hết mình hơn'},{k:'b',t:'Chia theo đợt, có mốc đánh giá và điều khoản chấm dứt'},
             {k:'c',t:'Không ký hợp đồng, chỉ thoả thuận miệng cho linh hoạt'},{k:'d',t:'Ký hợp đồng thật dài 12 tháng để có giá ưu đãi nhất'}],
    answer:'b', why:{a:'Trả trước toàn bộ làm mất đòn bẩy khi cần điều chỉnh.',
      b:'Đúng. Chia đợt và có mốc giúp dừng đúng lúc mà không vi phạm.',
      c:'Thoả thuận miệng dễ hiểu lầm cho cả hai bên.',
      d:'Cam kết dài mà không có điều khoản dừng làm tăng rủi ro.'} },
  { type:'mcq', stem:'Tình huống mới: một quán cà phê đã ký với một nhà in 6 tháng in ly giấy theo chủ đề chiến dịch. Sau 2 tháng chiến dịch đổi hướng. Lựa chọn nào hợp lý nhất?',
    options:[{k:'a',t:'Ngừng nhận hàng, để nhà in tự xử lý số ly đã in sẵn'},{k:'b',t:'Tiếp tục in ly cũ đủ 6 tháng dù chiến dịch đã đổi hướng'},
             {k:'c',t:'Đăng lên mạng than phiền nhà in để có lý do huỷ hợp đồng'},{k:'d',t:'Bàn với nhà in đổi mẫu in cho các tháng còn lại, giữ khối lượng'}],
    answer:'d', why:{a:'Đẩy thiệt hại cho đối tác là vi phạm cam kết.',
      b:'Giữ mẫu cũ khi chiến dịch đổi làm thông điệp lệch nhau.',
      c:'Bịa cớ công khai vừa sai vừa gây rủi ro pháp lý.',
      d:'Đúng. Giữ phần cam kết (khối lượng), thương lượng phần linh hoạt (mẫu).'} },
  { type:'mcq', stem:'Vì sao nên nói chuyện với đối tác sớm thay vì chờ tới hạn cuối?',
    options:[{k:'a',t:'Vì càng sớm, càng nhiều phần chưa thực hiện có thể điều chỉnh'},{k:'b',t:'Vì đối tác thường quên hợp đồng nếu không được nhắc'},
             {k:'c',t:'Vì nói sớm thì không phải trả tiền cho phần đã làm xong'},{k:'d',t:'Vì hợp đồng tự hết hiệu lực nếu một bên báo trước'}],
    answer:'a', why:{a:'Đúng. Phần chưa làm là phần duy nhất còn thương lượng được.',
      b:'Không nên dựa vào việc đối tác quên.',
      c:'Phần đã làm vẫn phải trả theo thoả thuận.',
      d:'Hợp đồng không tự hết hiệu lực chỉ vì báo trước, trừ khi có điều khoản như vậy.'} },
  { type:'mcq', stem:'Khi chia sẻ số liệu kém với KOL, cách nói nào phù hợp nhất?',
    options:[{k:'a',t:'“Video của bạn không hiệu quả, mình phải cắt hợp đồng thôi”'},{k:'b',t:'“Sếp mình không hài lòng, mình cũng không biết làm sao được”'},
             {k:'c',t:'“Mã của bạn mới ra 12 đơn; mình cùng thử hướng khác được không?”'},{k:'d',t:'“Chắc tại khán giả của bạn không có tiền mua serum giá này”'}],
    answer:'c', why:{a:'Đổ lỗi và ra quyết định một chiều khiến đối tác phòng thủ.',
      b:'Né tránh trách nhiệm không tạo ra phương án.',
      c:'Đúng. Số liệu thật, không phán xét, mở ra cùng tìm cách.',
      d:'Nhận xét về khán giả của đối tác là xúc phạm và không có căn cứ.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tu06-08', skill:'measure', read:'7 phút', t:'Doanh thu chiến dịch vẫn cao — sao lại nói nên dừng?',
  situation:'Một shop nồi chiên không dầu chạy chiến dịch Black Friday: chi 50 triệu quảng cáo, ra 400 đơn, doanh thu 480 triệu. Báo cáo ghi “ROAS 9,6 — rất tốt”. Nhưng mỗi nồi giá bán 1,2 triệu, giá vốn 850.000đ, phí sàn và vận chuyển 180.000đ. Kế toán nói chiến dịch đang lỗ.',
  concept:{ name:'Lãi biên sau quảng cáo',
    body:'Doanh thu và ROAS (doanh thu ÷ chi quảng cáo) không nói bạn lãi hay lỗ. Muốn biết, tính <b>lãi biên mỗi đơn</b>: giá bán trừ giá vốn trừ mọi chi phí biến đổi (phí sàn, vận chuyển, khuyến mãi, hoàn hàng). Nhân với số đơn rồi trừ chi quảng cáo. Nếu kết quả âm, chiến dịch đang mua doanh thu bằng tiền lỗ. Trước khi quyết dừng hay chạy, luôn đọc con số này, và hỏi thêm: khách mua lần này có quay lại mua đủ để bù không?' },
  example:'Lãi biên mỗi nồi: 1.200.000 − 850.000 − 180.000 = 170.000đ. 400 đơn → 68 triệu. Trừ 50 triệu quảng cáo → lãi 18 triệu. Nhưng ưu đãi Black Friday tặng kèm khay giấy 60.000đ mỗi đơn mà báo cáo quên: 400 × 60.000 = 24 triệu. Kết quả: lỗ 6 triệu. Nồi chiên ít khi mua lặp lại, nên không có lý do để chạy tiếp ở mức ưu đãi này; shop dừng và chỉ chạy lại khi bỏ quà tặng.',
  takeaway:'ROAS cao chưa chắc có lãi; trừ hết chi phí biến đổi và quảng cáo rồi mới quyết.',
  apply:'Chọn một sản phẩm bạn biết giá. Nói trong 60 giây: giá bán, giá vốn, chi phí biến đổi — mỗi đơn lãi bao nhiêu trước quảng cáo?',
  mistakes:['Xem ROAS như lợi nhuận.','Quên chi phí quà tặng, phí sàn, hoàn hàng khi tính lãi chiến dịch.'],
  q:[
  { type:'mcq', stem:'Chiến dịch có ROAS 9,6. Theo bạn, điều đó có chắc là chiến dịch có lãi không?',
    options:[{k:'a',t:'Có, vì doanh thu gấp gần 10 lần tiền quảng cáo đã bỏ ra'},{k:'b',t:'Có, vì ROAS trên 3 luôn được xem là có lãi trong thương mại điện tử'},
             {k:'c',t:'Chưa chắc, phải trừ giá vốn và chi phí biến đổi mới biết'},{k:'d',t:'Không, vì ROAS cao thường là dấu hiệu số liệu bị đếm trùng'}],
    answer:'c', why:{a:'Doanh thu chưa trừ giá vốn và chi phí; ROAS không phải lợi nhuận.',
      b:'Không có ngưỡng chung; ngưỡng phụ thuộc lãi biên của từng sản phẩm.',
      c:'Đúng. Chỉ khi trừ hết chi phí mới biết lãi hay lỗ.',
      d:'ROAS cao không tự chứng minh đếm trùng.'} },
  { type:'mcq', stem:'Kế toán tính ra lỗ 6 triệu do quà tặng khay giấy. Nồi chiên ít mua lặp lại. Bạn chọn gì?',
    options:[{k:'a',t:'Chạy tiếp vì doanh thu cao giúp shop tăng hạng trên sàn thương mại'},{k:'b',t:'Dừng, chỉ chạy lại khi bỏ quà tặng hoặc lãi biên dương'},
             {k:'c',t:'Tăng ngân sách để có nhiều đơn hơn, lỗ sẽ được chia nhỏ'},{k:'d',t:'Giữ nguyên, vì 6 triệu lỗ là nhỏ so với 480 triệu doanh thu'}],
    answer:'b', why:{a:'Tăng hạng có giá trị, nhưng không có kế hoạch đo thì đó là lý do cảm tính để chịu lỗ.',
      b:'Đúng. Sản phẩm ít mua lại thì không có lãi sau để bù, nên dừng và sửa ưu đãi.',
      c:'Mỗi đơn đang lỗ thì thêm đơn là thêm lỗ.',
      d:'So lỗ với doanh thu là so sai đơn vị; lỗ vẫn là lỗ.'} },
  { type:'calc', stem:'Giá bán 1.200.000đ, giá vốn 850.000đ, phí sàn và vận chuyển 180.000đ, quà tặng 60.000đ mỗi đơn. 400 đơn, chi quảng cáo 50 triệu. Chiến dịch lãi (dương) hay lỗ (âm) bao nhiêu triệu?',
    unit:'triệu đồng', ans:-6, tol:0.1, wrong:[[18,'QUEN_CHI_PHI_KHUYEN_MAI'],[430,'ROAS_LA_LOI_NHUAN']], errors:['QUEN_CHI_PHI_KHUYEN_MAI','ROAS_LA_LOI_NHUAN'],
    steps:['Lãi biên mỗi đơn: 1.200.000 − 850.000 − 180.000 − 60.000 = 110.000đ.','400 đơn × 110.000đ = 44 triệu.','44 − 50 = <b>−6 triệu</b>.'] },
  { type:'mcq', stem:'Khoản nào KHÔNG thuộc chi phí biến đổi mỗi đơn khi tính lãi biên chiến dịch?',
    options:[{k:'a',t:'Phí sàn thu theo phần trăm trên giá trị từng đơn hàng'},{k:'b',t:'Phí vận chuyển mà shop trả cho mỗi kiện hàng gửi đi'},
             {k:'c',t:'Quà tặng kèm theo mỗi đơn trong thời gian ưu đãi'},{k:'d',t:'Tiền thuê kho hàng tháng, trả cố định dù bán ít hay nhiều'}],
    answer:'d', why:{a:'Phí sàn tăng theo từng đơn — là chi phí biến đổi.',
      b:'Mỗi đơn một phí vận chuyển — chi phí biến đổi.',
      c:'Mỗi đơn một quà — chi phí biến đổi.',
      d:'Đúng. Tiền thuê kho cố định, không đổi theo số đơn của chiến dịch.'} },
  { type:'mcq', stem:'Tình huống mới: một thương hiệu cà phê hạt chạy chiến dịch lỗ 2 triệu mỗi 100 khách mới. Dữ liệu cũ cho thấy 40% khách mới mua lại, mỗi lần mua lại lãi biên 90.000đ. Nên đọc thế nào?',
    options:[{k:'a',t:'Lỗ ngay thì phải dừng, không cần nhìn thêm gì khác'},{k:'b',t:'Chỉ cần ROAS trên 2 là chiến dịch chắc chắn đáng chạy tiếp'},
             {k:'c',t:'Tính lãi từ lần mua lại để xem có bù được 2 triệu không'},{k:'d',t:'Tăng giá cà phê để lần đầu mua đã có lãi ngay cho yên tâm'}],
    answer:'c', why:{a:'Với hàng mua lặp lại, lỗ lần đầu có thể là đầu tư nếu lần sau bù được.',
      b:'ROAS không nói gì về lãi và mua lại.',
      c:'Đúng. 40 khách × 90.000đ = 3,6 triệu từ một lần mua lại — đủ bù 2 triệu nếu dữ liệu mua lại đáng tin.',
      d:'Tăng giá có thể giảm khách mới; chưa cần khi phép tính mua lại đang dương.'} },
  { type:'mcq', stem:'Vì sao báo cáo chiến dịch thường chỉ ghi doanh thu và ROAS?',
    options:[{k:'a',t:'Vì hai con số đó có sẵn trên trang quảng cáo, còn giá vốn thì không'},{k:'b',t:'Vì doanh thu phản ánh chính xác lợi nhuận của từng chiến dịch'},
             {k:'c',t:'Vì kế toán cấm bộ phận marketing tiếp cận số liệu giá vốn'},{k:'d',t:'Vì ROAS đã trừ sẵn giá vốn và mọi chi phí biến đổi rồi'}],
    answer:'a', why:{a:'Đúng. Nền tảng quảng cáo chỉ thấy doanh thu; lãi phải tự ghép với số liệu giá vốn.',
      b:'Doanh thu không phản ánh lợi nhuận.',
      c:'Không có quy định chung như vậy; thường chỉ là chưa ai ghép số.',
      d:'ROAS không trừ chi phí nào ngoài việc chia cho tiền quảng cáo.'} },
  { type:'mcq', stem:'Trước khi quyết dừng một chiến dịch, câu hỏi nào nên hỏi đầu tiên?',
    options:[{k:'a',t:'Mỗi đơn, sau mọi chi phí và quảng cáo, còn lãi hay lỗ?'},{k:'b',t:'Doanh thu tháng này có cao hơn cùng kỳ năm ngoái không?'},
             {k:'c',t:'Đối thủ có đang chạy chiến dịch mạnh hơn mình không?'},{k:'d',t:'Video quảng cáo có được nhiều lượt thích và chia sẻ không?'}],
    answer:'a', why:{a:'Đúng. Đây là con số quyết định chiến dịch đang tạo hay đốt giá trị.',
      b:'Doanh thu cùng kỳ bị trộn nhiều yếu tố ngoài chiến dịch.',
      c:'Đối thủ không làm thay đổi lãi lỗ của bạn trên từng đơn.',
      d:'Lượt thích không nói gì về lãi.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tu06-09', skill:'comm', read:'6 phút', t:'Dừng chương trình khuyến mãi: báo khách và đối tác thế nào?',
  situation:'Một chuỗi gà rán địa phương có chương trình “thẻ tích điểm, 10 lần tặng 1 phần” chạy 6 tháng. Chi phí quá cao nên công ty quyết định dừng từ tháng sau. Khoảng 3.000 khách đang giữ thẻ dang dở, 8 đại lý giao hàng đã in chương trình lên menu của họ.',
  concept:{ name:'Thông báo dừng',
    body:'Dừng một chiến dịch đang chạy là thay đổi lời hứa với người đã tham gia. Làm đúng thì ít ai phàn nàn; làm vội thì mất lòng khách trung thành nhất. Ba nguyên tắc: <b>báo trước</b> đủ thời gian (ví dụ 30 ngày); <b>tôn trọng phần đã tích</b> — cho đổi quà sớm hoặc quy đổi; và <b>báo đối tác trước khách</b>, vì họ phải sửa menu, tài liệu. Nói lý do ngắn gọn, thật, không đổ lỗi. Nếu có chương trình thay thế, nói luôn trong cùng thông báo.' },
  example:'Chuỗi gà rán báo 8 đại lý trước 2 tuần, gửi file menu mới. Sau đó thông báo khách: chương trình kết thúc ngày 30; ai có từ 5 dấu trở lên được đổi một phần nhỏ, ai đủ 10 được đổi phần lớn như cũ tới hết tháng sau. Khoảng 1.200 khách có từ 5 dấu; chi phí quy đổi dự kiến thấp hơn nhiều so với duy trì chương trình thêm 6 tháng, và gần như không có phàn nàn.',
  takeaway:'Báo đối tác trước, báo khách đủ sớm, và tôn trọng phần khách đã tích luỹ.',
  apply:'Viết trong 60 giây câu đầu tiên của thông báo dừng một chương trình tích điểm, đủ lý do và phương án cho khách.',
  mistakes:['Dừng ngay trong ngày, huỷ luôn điểm khách đã tích.','Quên báo đối tác nên menu cũ vẫn lưu hành, khách đến đòi quyền lợi.'],
  q:[
  { type:'mcq', stem:'Chuỗi gà rán muốn dừng chương trình tích điểm. Theo bạn, nhóm nào dễ phật lòng nhất nếu làm vội?',
    options:[{k:'a',t:'Khách mới chưa từng mua lần nào tại cửa hàng'},{k:'b',t:'Khách trung thành đang giữ thẻ gần đủ dấu'},
             {k:'c',t:'Nhân viên bếp vì phải làm thêm phần tặng'},{k:'d',t:'Đối thủ cạnh tranh sẽ được lợi thêm khách hàng'}],
    answer:'b', why:{a:'Khách mới chưa tham gia nên ít bị ảnh hưởng.',
      b:'Đúng. Người đã đầu tư nhiều lần mua nhất là người mất nhiều nhất khi bị huỷ.',
      c:'Dừng chương trình làm bếp bớt việc chứ không thêm.',
      d:'Đối thủ không phải người “phật lòng”.'} },
  { type:'mcq', stem:'Bạn chịu trách nhiệm thông báo. Bạn chọn thứ tự nào?',
    options:[{k:'a',t:'Báo khách trên fanpage trước, đại lý đọc được thì tự sửa menu'},{k:'b',t:'Báo khách và đại lý cùng lúc trong ngày cuối của chương trình'},
             {k:'c',t:'Chỉ gỡ chương trình khỏi menu tại quán, không cần thông báo'},{k:'d',t:'Báo đại lý trước 2 tuần, rồi báo khách kèm cách đổi điểm'}],
    answer:'d', why:{a:'Đại lý không kịp sửa, menu cũ vẫn chạy và khách đòi quyền lợi.',
      b:'Báo trong ngày cuối không cho ai thời gian chuẩn bị.',
      c:'Im lặng khiến khách giữ thẻ thấy bị lừa.',
      d:'Đúng. Đối tác cần thời gian sửa tài liệu; khách cần biết cách giữ quyền lợi.'} },
  { type:'calc', stem:'3.000 khách đang giữ thẻ, 40% có từ 5 dấu trở lên và được đổi một phần nhỏ giá vốn 25.000đ. Chi phí quy đổi dự kiến là bao nhiêu triệu đồng nếu tất cả nhóm này đến đổi?',
    unit:'triệu đồng', ans:30, tol:0.1, wrong:[[75,'SAI_MAU_SO'],[12,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số khách đủ điều kiện: 3.000 × 40% = 1.200.','Chi phí: 1.200 × 25.000đ = <b>30 triệu</b>.'] },
  { type:'mcq', stem:'Thông báo dừng nên nói lý do thế nào?',
    options:[{k:'a',t:'Ngắn, thật, không đổ lỗi, kèm phương án cho khách'},{k:'b',t:'Không nêu lý do để tránh bị khách hỏi thêm và bàn tán trên mạng'},
             {k:'c',t:'Nói do khách lạm dụng chương trình quá nhiều lần'},{k:'d',t:'Nói do quy định mới của nhà nước dù không đúng'}],
    answer:'a', why:{a:'Đúng. Thật và ngắn giúp khách chấp nhận dễ hơn.',
      b:'Không nói gì khiến khách tự suy diễn, thường theo hướng xấu.',
      c:'Đổ lỗi cho khách làm mất lòng nhóm khách trung thành.',
      d:'Bịa lý do dễ bị lật tẩy và gây rủi ro.'} },
  { type:'mcq', stem:'Tình huống mới: một ứng dụng giao đồ ăn muốn ngừng gói thành viên miễn phí ship. Nhiều người đã trả trước 12 tháng. Cách nào hợp lý nhất?',
    options:[{k:'a',t:'Huỷ tất cả gói ngay và tặng mỗi người một mã giảm giá nhỏ'},{k:'b',t:'Giữ quyền lợi tới hết kỳ đã trả, ngừng bán gói mới, báo trước'},
             {k:'c',t:'Giảm dần quyền lợi mỗi tháng mà không thông báo cho khách'},{k:'d',t:'Chuyển mọi người sang gói khác đắt hơn và tự trừ thêm tiền'}],
    answer:'b', why:{a:'Huỷ gói đã trả tiền là phá cam kết; mã nhỏ không bù được.',
      b:'Đúng. Tôn trọng phần khách đã trả, dừng từ phía bán mới.',
      c:'Lặng lẽ giảm quyền lợi dễ bị phát hiện và mất niềm tin.',
      d:'Tự trừ tiền khi khách chưa đồng ý là sai nghiêm trọng.'} },
  { type:'mcq', stem:'Vì sao nên báo trước khoảng 30 ngày thay vì vài ngày?',
    options:[{k:'a',t:'Vì luật bắt buộc mọi chương trình phải báo trước đúng 30 ngày'},{k:'b',t:'Vì thông báo sớm giúp chương trình kéo thêm được nhiều khách mới'},
             {k:'c',t:'Vì khách có thời gian dùng nốt quyền lợi, bớt cảm giác bị ép'},{k:'d',t:'Vì 30 ngày đủ để khách quên chương trình và không đòi đổi'}],
    answer:'c', why:{a:'Bài này không khẳng định mốc pháp lý cụ thể; 30 ngày là mốc gợi ý về sự tôn trọng.',
      b:'Thông báo dừng không nhằm kéo khách mới.',
      c:'Đúng. Có thời gian thì khách thấy được đối xử công bằng.',
      d:'Mong khách quên là tư duy gây mất niềm tin.'} },
  { type:'mcq', stem:'Nếu có chương trình thay thế, nên đưa vào thông báo khi nào?',
    options:[{k:'a',t:'Để dành vài tháng sau cho khách có cảm giác bất ngờ'},{k:'b',t:'Chỉ nói riêng với khách than phiền nhiều nhất trên mạng'},
             {k:'c',t:'Không nên nhắc, vì dễ làm khách so sánh hai chương trình'},{k:'d',t:'Nói luôn trong cùng thông báo dừng để khách thấy còn quyền lợi'}],
    answer:'d', why:{a:'Khoảng trống vài tháng khiến khách nghĩ mình bị bỏ rơi.',
      b:'Ưu đãi ngầm cho người than phiền là không công bằng.',
      c:'Khách sẽ so sánh dù bạn có nói hay không.',
      d:'Đúng. Tin dừng đi kèm tin thay thế giúp giảm cảm giác mất mát.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:tu06-10', skill:'measure', read:'6 phút', t:'Chiến dịch đã tắt — cần lưu lại những gì?',
  situation:'Một thương hiệu balo học sinh vừa kết thúc chiến dịch mùa tựu trường, chi 150 triệu trên 3 kênh. Người chạy chính sắp nghỉ việc. Năm sau, người mới sẽ phải làm lại từ đầu nếu không ai ghi lại gì — điều đã xảy ra năm ngoái.',
  concept:{ name:'Hồ sơ đóng chiến dịch',
    body:'Khi dừng, thứ đáng giá nhất còn lại là <b>những gì đã học</b>. Một hồ sơ đóng chiến dịch nên có: mục tiêu ban đầu và kết quả thật; chi phí và lãi biên theo từng kênh; creative nào tốt, creative nào tệ và giả thuyết vì sao; lý do dừng và thời điểm dừng; tệp khách hàng, danh sách đối tác, hợp đồng; và 3 điều sẽ làm khác lần sau. Viết ngay khi vừa dừng, khi mọi người còn nhớ, và để ở nơi người mới tìm được.' },
  example:'Hồ sơ của thương hiệu balo ghi: TikTok chi 70 triệu, lãi biên sau quảng cáo 22 triệu; Facebook chi 50 triệu, hoà vốn; KOL chi 30 triệu, lỗ 8 triệu. Video “thử balo nặng 5 kg trên lưng” có chi phí mỗi đơn thấp nhất. Dừng ngày 5/9 vì nhu cầu giảm rõ sau khai giảng. Lần sau: bắt đầu sớm hơn 1 tuần, cắt KOL, giữ dạng video thử nghiệm thực tế.',
  takeaway:'Chiến dịch đóng lại, bài học phải được viết ra và để nơi người sau tìm được.',
  apply:'Nói trong 60 giây: 3 điều bạn sẽ ghi vào hồ sơ đóng của chiến dịch gần nhất bạn làm hoặc biết.',
  mistakes:['Chỉ lưu báo cáo tổng doanh thu, không lưu số theo kênh và creative.','Để hồ sơ trong máy cá nhân, người mới không tìm thấy.'],
  q:[
  { type:'mcq', stem:'Người chạy chiến dịch sắp nghỉ. Theo bạn, thứ gì dễ mất nhất nếu không ghi lại?',
    options:[{k:'a',t:'Số tiền đã chi, vì kế toán sẽ không lưu hoá đơn quảng cáo'},{k:'b',t:'Lý do chọn creative, kênh và thời điểm dừng — nằm trong đầu người chạy'},
             {k:'c',t:'Tài khoản quảng cáo, vì nền tảng sẽ xoá khi chiến dịch kết thúc'},{k:'d',t:'Logo và bộ nhận diện của thương hiệu balo đã dùng cho chiến dịch'}],
    answer:'b', why:{a:'Chi phí thường có hoá đơn, kế toán lưu.',
      b:'Đúng. Số liệu thô còn trên hệ thống, nhưng “vì sao” chỉ người chạy biết.',
      c:'Tài khoản không bị xoá khi chiến dịch dừng.',
      d:'Bộ nhận diện được lưu ở nơi khác, không phụ thuộc chiến dịch.'} },
  { type:'mcq', stem:'Bạn có 1 giờ trước khi người chạy chính nghỉ. Bạn ưu tiên ghi gì?',
    options:[{k:'a',t:'Tổng doanh thu và ảnh chụp những quảng cáo đẹp nhất của cả mùa tựu trường'},{k:'b',t:'Danh sách mật khẩu tài khoản để người mới đăng nhập được ngay'},
             {k:'c',t:'Lãi biên theo kênh, creative tốt/tệ, lý do dừng, 3 điều làm khác'},{k:'d',t:'Lời cảm ơn gửi cả nhóm và đối tác đã tham gia chiến dịch'}],
    answer:'c', why:{a:'Tổng doanh thu không cho biết nên làm gì khác lần sau.',
      b:'Quyền truy cập nên bàn giao qua quản trị tài khoản, không ghi mật khẩu vào hồ sơ.',
      c:'Đúng. Đây là phần giúp người sau ra quyết định tốt hơn.',
      d:'Cảm ơn là tốt, nhưng không thay được bài học.'} },
  { type:'calc', stem:'TikTok chi 70 triệu, lãi biên trước quảng cáo 92 triệu. Facebook chi 50 triệu, lãi biên trước quảng cáo 50 triệu. KOL chi 30 triệu, lãi biên trước quảng cáo 22 triệu. Tổng lãi sau quảng cáo của chiến dịch là bao nhiêu triệu?',
    unit:'triệu đồng', ans:14, tol:0.1, wrong:[[164,'QUEN_TRU_CHI_PHI_QC'],[22,'SAI_TINH_TOAN']], errors:['QUEN_TRU_CHI_PHI_QC','SAI_TINH_TOAN'],
    steps:['TikTok: 92 − 70 = 22.','Facebook: 50 − 50 = 0.','KOL: 22 − 30 = −8.','Tổng: 22 + 0 − 8 = <b>14 triệu</b>.'] },
  { type:'mcq', stem:'Vì sao nên viết hồ sơ đóng ngay khi vừa dừng, không đợi cuối quý?',
    options:[{k:'a',t:'Vì số liệu trên nền tảng quảng cáo sẽ bị xoá sau một tháng'},{k:'b',t:'Vì sếp thường chỉ đọc báo cáo trong đúng tuần đầu tiên sau khi chiến dịch kết thúc'},
             {k:'c',t:'Vì viết sớm thì chiến dịch sau được duyệt nhanh hơn'},{k:'d',t:'Vì lý do và giả thuyết phai nhanh trong trí nhớ mọi người'}],
    answer:'d', why:{a:'Số liệu thường còn lâu hơn; cái mất là phần giải thích.',
      b:'Không phải lý do chính.',
      c:'Không có liên hệ trực tiếp.',
      d:'Đúng. Sau vài tuần, người ta nhớ kết quả nhưng quên vì sao đã quyết định.'} },
  { type:'mcq', stem:'Tình huống mới: một quán lẩu dừng chiến dịch “lẩu nửa giá thứ ba” sau 2 tháng. Mục nào trong hồ sơ giúp lần sau tránh lặp lỗi nhất?',
    options:[{k:'a',t:'Lý do dừng: thứ ba kín bàn nhưng khách chuyển từ ngày khác sang'},{k:'b',t:'Ảnh chụp quán đông khách vào các tối thứ ba trong 2 tháng chạy'},
             {k:'c',t:'Tổng số bài đăng trên fanpage của quán trong suốt thời gian chiến dịch'},{k:'d',t:'Tên nhân viên đã đề xuất ý tưởng chương trình khuyến mãi này'}],
    answer:'a', why:{a:'Đúng. Hiểu rằng khuyến mãi chỉ dời khách chứ không thêm khách là bài học đổi được quyết định sau.',
      b:'Ảnh đông khách dễ khiến lần sau lặp lại đúng sai lầm.',
      c:'Số bài đăng không nói lên hiệu quả.',
      d:'Tên người đề xuất không giúp tránh lỗi.'} },
  { type:'mcq', stem:'Hồ sơ đóng chiến dịch nên lưu ở đâu?',
    options:[{k:'a',t:'Trong máy tính cá nhân của người chạy cho bảo mật'},{k:'b',t:'Ở thư mục chung của nhóm, đặt tên theo chiến dịch và năm'},
             {k:'c',t:'Trong tin nhắn nhóm chat để ai cũng xem được ngay'},{k:'d',t:'In ra giấy và cất trong tủ tài liệu của phòng kế toán'}],
    answer:'b', why:{a:'Người nghỉ việc mang theo máy; hồ sơ mất theo.',
      b:'Đúng. Nơi chung, tên rõ ràng, người mới tìm được.',
      c:'Tin nhắn trôi mất, rất khó tìm lại sau vài tháng.',
      d:'Bản giấy khó tìm và khó chia sẻ.'} },
  { type:'mcq', stem:'Mục “3 điều làm khác lần sau” có tác dụng gì nhất?',
    options:[{k:'a',t:'Để chứng minh người chạy chiến dịch đã làm việc chăm chỉ'},{k:'b',t:'Để kế toán dễ đối chiếu số liệu chi phí quảng cáo vào cuối năm tài chính'},
             {k:'c',t:'Biến kết quả thành quyết định cụ thể cho chiến dịch kế tiếp'},{k:'d',t:'Để đối tác biết thương hiệu sẽ cắt giảm hợp đồng năm sau'}],
    answer:'c', why:{a:'Không phải bản thành tích cá nhân.',
      b:'Kế toán cần số liệu, không cần mục này.',
      c:'Đúng. Bài học chỉ có giá trị khi thành hành động cho lần sau.',
      d:'Hồ sơ nội bộ, không nhằm báo đối tác.'} }
  ] }

]});
